@Composable
fun ClinicalRiskBadge(isHighRisk: Boolean, modifier: Modifier = Modifier) {
    if (isHighRisk) {
        ClinicalTagBadge(
            text = stringResource(R.string.high_risk),
            showWarningIcon = true,
            isError = true,
            modifier = modifier,
        )
    } else {
        ClinicalTagBadge(
            text = stringResource(R.string.normal_risk_filter),
            showWarningIcon = false,
            isError = false,
            modifier = modifier,
        )
    }
}

